esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// MemAvailable, never MemFree: PostgreSQL relies on the page cache, so free memory is
// expected to sit near zero while available memory is healthy. MIN() on the available
// side and MAX() on the capacity side give the worst-case headroom in the window.
| STATS
    `Available Bytes` = MIN(LAST_OVER_TIME(node_memory_MemAvailable_bytes)),
    `Total Bytes` = MAX(LAST_OVER_TIME(node_memory_MemTotal_bytes)),
    `Swap Total Bytes` = MAX(LAST_OVER_TIME(node_memory_SwapTotal_bytes)),
    `Swap Free Bytes` = MIN(LAST_OVER_TIME(node_memory_SwapFree_bytes)),
    `Dirty Bytes` = MAX(MAX_OVER_TIME(node_memory_Dirty_bytes))
  BY resource.attributes.supabase_project_ref
| WHERE `Total Bytes` > 0
| EVAL `Available Memory %` = ROUND(`Available Bytes` / `Total Bytes` * 100, 1)
// Swap usage is diagnostic context; null when the node has no swap configured.
| EVAL `Swap Used %` = CASE(
    `Swap Total Bytes` > 0, ROUND((1 - `Swap Free Bytes` / `Swap Total Bytes`) * 100, 1)
  )
// Below 10% available the buffer cache is being squeezed and an OOM kill is the next step.
// Raise to 15 on memory-tight compute tiers for earlier warning.
| WHERE `Available Memory %` < 10
